function Content(){const[items,setItems]=useState([]),[notices,setNotices]=useState([]),[section,setSection]=useState('content'),[title,setTitle]=useState(''),[body,setBody]=useState(''),[type,setType]=useState('content'),[tags,setTags]=useState([]),[startsAt,setStartsAt]=useState(''),[endsAt,setEndsAt]=useState(''),[published,setPublished]=useState(true),[featured,setFeatured]=useState(false),[message,setMessage]=useState(''),[editing,setEditing]=useState(null);
 const editorRef=useRef(null);const tagOptions=['Banhos','Ensinamentos','Recados dos Pais da Casa','Macumbas de Terreiro'];const labels={content:'Conteúdo',rule:'Regra da casa',notice:'Aviso da casa'};
 const cleanHtml=html=>String(html||'').replace(/<script[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style[^>]*>[\s\S]*?<\/style>/gi,'');
 const toInputDate=s=>s?new Date(s).toISOString().slice(0,16):'';
 const load=async()=>{const [{data:hc,error:he},{data:no,error:ne}]=await Promise.all([supabase.from('house_contents').select('*').order('sort_order').order('created_at',{ascending:false}),supabase.rpc('editor_list_notices')]);if(he)setMessage(err(he));if(ne)setMessage(err(ne));setItems(hc||[]);setNotices(no||[])};
 useEffect(()=>{load()},[]);
 const clear=()=>{setTitle('');setBody('');setType('content');setTags([]);setStartsAt('');setEndsAt('');setPublished(true);setFeatured(false);setEditing(null);if(editorRef.current)editorRef.current.innerHTML=''};
 const startEdit=x=>{setEditing({kind:x._kind,id:x.id});setTitle(x.title);setType(x._kind);setTags(Array.isArray(x.tags)?x.tags:[]);setBody(x.body||'');setStartsAt(toInputDate(x.starts_at));setEndsAt(toInputDate(x.ends_at));setPublished(x.published!==false);setFeatured(!!x.featured);if(editorRef.current)editorRef.current.innerHTML=/<[a-z][\s\S]*>/i.test(x.body||'')?cleanHtml(x.body):textToHtml(x.body);window.scrollTo({top:0,behavior:'smooth'})};
 const save=async()=>{const html=cleanHtml(editorRef.current?.innerHTML||body);const plain=html.replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').trim();if(!title.trim()||!plain){setMessage('Preencha título e texto.');return}let error=null;if(type==='notice'){const q=editing?.kind==='notice'?supabase.rpc('editor_update_notice',{p_id:editing.id,p_title:title.trim(),p_body:html,p_starts_at:startsAt?new Date(startsAt).toISOString():null,p_ends_at:endsAt?new Date(endsAt).toISOString():null,p_published:published}):supabase.rpc('editor_create_notice',{p_title:title.trim(),p_body:html,p_starts_at:startsAt?new Date(startsAt).toISOString():null,p_ends_at:endsAt?new Date(endsAt).toISOString():null,p_published:published});({error}=await q)}else{const q=editing?.kind==='content'||editing?.kind==='rule'?supabase.rpc('editor_update_house_content',{p_id:editing.id,p_title:title.trim(),p_body:html,p_content_type:type,p_tags:type==='content'?tags:[],p_featured:type==='content'?featured:false}):supabase.rpc('editor_create_house_content',{p_title:title.trim(),p_body:html,p_content_type:type,p_tags:type==='content'?tags:[],p_sort_order:items.length});({error}=await q)}if(error)setMessage(err(error));else{clear();setMessage(type==='notice'?(editing?'Aviso atualizado.':'Aviso publicado.'):editing?(type==='rule'?'Regra atualizada.':'Conteúdo atualizado.'):(type==='rule'?'Regra publicada.':'Conteúdo publicado.'));load()}};
 const remove=async x=>{if(!confirm('Excluir este item?'))return;const {error}=await (x._kind==='notice'?supabase.rpc('editor_delete_notice',{p_id:x.id}):supabase.rpc('editor_delete_house_content',{p_id:x.id}));if(error)setMessage(err(error));else{setMessage('Item excluído.');load()}};
 const all=[...items.filter(x=>x.content_type==='content').map(x=>({...x,_kind:'content'})),...items.filter(x=>x.content_type==='rule').map(x=>({...x,_kind:'rule'})),...notices.map(x=>({...x,_kind:'notice'}))];
 const beginNew=k=>{clear();setType(k);setSection(k)};
 return <div className="house-admin"><div className="section-heading"><div><span className="eyebrow">GESTÃO DA CASA</span><h2>Conteúdos da casa</h2><p className="muted">Publique conteúdos, avisos e regras em seus próprios ambientes.</p></div></div>{message&&<div className="toast">{message}</div>}
   <div className="content-admin-tabs">{[['content','Conteúdos'],['notice','Avisos da Casa'],['rule','Regras da Casa']].map(([k,l])=><button key={k} className={'btn '+(section===k?'primary':'')} onClick={()=>{setSection(k);if(!editing)setType(k)}}>{l}</button>)}</div>
   <div className="content-editor"><div className="content-editor-head"><div><span className="pill">{editing?labels[type].toUpperCase():'NOVA PUBLICAÇÃO'}</span><h3>{editing?'Editar':'Novo'} {labels[type].toLowerCase()}</h3><p className="muted small">{type==='content'?'Um artigo para o blog interno da casa.':type==='notice'?'Um comunicado que pode ter período de exibição.':'Uma orientação permanente para consulta da comunidade.'}</p></div></div>
     <Field label="Título"><input className="input" placeholder={type==='notice'?'Ex.: Mudança no horário da gira':'Ex.: O poder das ervas no terreiro'} value={title} onChange={e=>setTitle(e.target.value)}/></Field>
     {type==='content'&&<div className="field"><label>Tags (opcional)</label><div className="tag-options">{tagOptions.map(t=><label className="btn" key={t}><input type="checkbox" checked={tags.includes(t)} onChange={e=>setTags(e.target.checked?[...tags,t]:tags.filter(x=>x!==t))}/> {t}</label>)}</div></div>}
     {type==='content'&&<label className="choice" style={{cursor:'pointer'}}><input type="checkbox" checked={featured} onChange={e=>setFeatured(e.target.checked)}/><span><b>Destacar na área de conteúdos</b><br/><small className="muted">O conteúdo pode aparecer em destaque no blog.</small></span></label>}
     {type==='notice'&&<><div className="grid"><Field label="Exibir a partir de"><input className="input" type="datetime-local" value={startsAt} onChange={e=>setStartsAt(e.target.value)}/></Field><Field label="Exibir até"><input className="input" type="datetime-local" value={endsAt} onChange={e=>setEndsAt(e.target.value)}/></Field></div><label className="choice" style={{cursor:'pointer'}}><input type="checkbox" checked={published} onChange={e=>setPublished(e.target.checked)}/><span><b>Publicado</b><br/><small className="muted">Desmarque para deixar o aviso oculto.</small></span></label></>}
     <div className="field"><label>Texto</label><div className="rich-toolbar"><button type="button" onMouseDown={e=>{e.preventDefault();execCommand(editorRef,'bold')}}><b>B</b></button><button type="button" onMouseDown={e=>{e.preventDefault();execCommand(editorRef,'italic')}}><i>I</i></button><button type="button" onMouseDown={e=>{e.preventDefault();execCommand(editorRef,'underline')}}><u>U</u></button><span></span><button type="button" onMouseDown={e=>{e.preventDefault();execCommand(editorRef,'insertUnorderedList')}}>• Lista</button><button type="button" onMouseDown={e=>{e.preventDefault();execCommand(editorRef,'insertOrderedList')}}>1. Lista</button><span></span><button type="button" onMouseDown={e=>{e.preventDefault();execCommand(editorRef,'removeFormat')}}>Limpar</button></div><div ref={editorRef} className="rich-editor" contentEditable suppressContentEditableWarning onInput={e=>setBody(e.currentTarget.innerHTML)} data-placeholder={type==='notice'?'Escreva o aviso…':type==='rule'?'Escreva a regra…':'Escreva o conteúdo…'}></div></div>
     <div className="row">{editing&&<button className="btn" onClick={clear}>Cancelar</button>}<button className="btn primary" onClick={save}>{editing?'Salvar alterações':type==='notice'?'Publicar aviso':type==='rule'?'Publicar regra':'Publicar conteúdo'}</button></div>
   </div>
   <div className="content-list-head"><div><span className="eyebrow">GESTÃO</span><h3>{section==='content'?'Conteúdos publicados':section==='notice'?'Avisos da Casa':'Regras da Casa'}</h3></div><span className="muted small">{all.filter(x=>x._kind===section).length} {all.filter(x=>x._kind===section).length===1?'item':'itens'}</span></div>
   <div className={section==='notice'?'notice-admin-list':section==='rule'?'rule-admin-list':'house-content-list'}>{!all.filter(x=>x._kind===section).length?<div className="card empty">Nenhum item publicado aqui.</div>:all.filter(x=>x._kind===section).map((x,i)=><article className={x._kind==='notice'?'notice-admin-card':x._kind==='rule'?'rule-admin-card':'house-content-card'} key={x.id}><div className="house-content-top"><span className="content-kind">{labels[x._kind]}</span><span className="content-number">{String(i+1).padStart(2,'0')}</span></div><h3>{x.title}</h3>{x._kind==='content'&&x.tags?.length>0&&<div className="content-tags">{x.tags.map(t=><span className="content-tag" key={t}>{t}</span>)}</div>}<div className="house-content-body" dangerouslySetInnerHTML={{__html:cleanHtml(x.body)}}/>{x._kind==='notice'&&<p className="muted small">{x.published===false?'Oculto':'Publicado'}{x.ends_at?' · até '+dateTime(x.ends_at):''}</p>}<div className="house-content-actions"><button className="btn" onClick={()=>startEdit(x)}><FileText size={14}/> Editar</button><button className="btn danger" onClick={()=>remove(x)}><Trash2 size={14}/> Excluir</button></div></article>)}</div>
 </div>}
