function Admin({p,editor=false}){const financeManager=!!p?.is_finance_manager;const[tab,setTab]=useState(editor?'giras':financeManager?'finance':'overview'),[taskGiraId,setTaskGiraId]=useState('');const nav=editor?[['giras','Giras'],['content','Conteúdos']]:financeManager?[['finance','Financeiro']]:[['overview','Visão'],['people','Pessoas'],['giras','Giras'],['finance','Financeiro'],['invites','Convites'],['content','Conteúdos'],['questions','Dúvidas']];return <div><div className="card" style={{marginBottom:12}}><div className="row"><ShieldCheck size={18}/><div><b>{editor?'Gestão da casa':financeManager?'Gestão Financeira':'Administração'}</b><div className="muted small">{editor?'Giras e tarefas':financeManager?'Mensalidades e cobranças':'Pessoas, giras, tarefas, financeiro e conteúdos'}</div></div></div></div><div className="admin-nav">{nav.map(([id,label])=><button className={'btn '+(tab===id?'primary':'')} key={id} onClick={()=>setTab(id)}>{label}</button>)}</div>{tab==='overview'&&<AdminOverview onNavigate={setTab}/>}{tab==='people'&&<People/>}{tab==='giras'&&<GiraTurnManager p={p} editor={editor}/>} {tab==='tasks'&&<TaskManager editor={editor} initialGiraId={taskGiraId}/>}  {tab==='finance'&&<AdminFinance/>}{tab==='invites'&&<Invites/>}{tab==='content'&&<Content/>}{tab==='questions'&&<AdminQuestions/>}</div>}
function AdminOverview({onNavigate}){const[stats,setStats]=useState(null),[loading,setLoading]=useState(true),[message,setMessage]=useState('');const load=async()=>{setLoading(true);setMessage('');try{const now=new Date();const month=now.toISOString().slice(0,7);const [{data:people},{data:dues},{data:charges},{data:giras},{data:questions},{data:contents}]=await Promise.all([supabase.from('profiles').select('id,name,email,date_of_birth,orixa_symbol,group_id,is_active,role,leadership_seal').eq('is_active',true).order('name'),supabase.from('monthly_dues').select('profile_id,status,reference_month').eq('reference_month',month+'-01'),supabase.from('extra_charges').select('id,profile_id,status,amount').eq('status','unpaid'),supabase.from('giras').select('*').gte('starts_at',now.toISOString()).order('starts_at').limit(1),supabase.rpc('admin_house_questions',{p_status:'open'}),supabase.from('house_contents').select('id')]);let next=giras?.[0]||null;let attendance=[];let tasks=[];if(next){const a=await supabase.rpc('editor_gira_attendance',{p_gira_id:next.id});attendance=a.data||[];const t=await supabase.from('tasks').select('id,name,slots,task_assignments(profile_id,assignment_mode)').eq('gira_id',next.id);tasks=t.data||[]}const eligiblePeople=(people||[]).filter(x=>financialEligible(x.date_of_birth,now,x.is_pai_de_santo));const paid=new Set((dues||[]).filter(x=>x.status==='paid').map(x=>x.profile_id));const unpaid=Math.max(0,eligiblePeople.length-paid.size);const noResponse=(attendance||[]).filter(x=>x.status==='no_response').length;const going=(attendance||[]).filter(x=>x.status==='going').length;const notGoing=(attendance||[]).filter(x=>x.status==='not_going').length;const regularAssigned=(tasks||[]).reduce((n,t)=>n+(t.task_assignments||[]).filter(a=>a.assignment_mode!=='leader_choice').length,0);const taskSlots=(tasks||[]).reduce((n,t)=>n+Number(t.slots||0),0);const assignedPeople=new Set((tasks||[]).flatMap(t=>(t.task_assignments||[]).filter(a=>a.assignment_mode!=='leader_choice').map(a=>a.profile_id)));const eligible=(attendance||[]).filter(x=>x.status==='going').length;const withoutTask=Math.max(0,eligible-assignedPeople.size);const incomplete=(people||[]).filter(x=>!x.date_of_birth||!x.orixa_symbol||!x.group_id).length;setStats({active:people?.length||0,unpaid,questions:(questions||[]).length,pendingCharges:charges?.length||0,pendingChargeTotal:(charges||[]).reduce((n,x)=>n+Number(x.amount||0),0),next,attendance,going,notGoing,noResponse,taskSlots,regularAssigned,withoutTask,incomplete,contentCount:contents?.length||0})}catch(e){setMessage(err(e))}finally{setLoading(false)}};useEffect(()=>{load()},[]);const action=(label,tab)=>{onNavigate(tab)};return <div><div className="row between"><div><span className="eyebrow">PAINEL DA CASA</span><h2>Visão</h2><p className="muted">Tudo o que precisa da atenção da administração, em um só lugar.</p></div><button className="btn" onClick={load}><RefreshCw size={14}/> Atualizar</button></div>{message&&<div className="toast">{message}</div>}{loading?<div className="card">Carregando o painel…</div>:stats&&<><div className="usage-summary"><div className="card"><b>{stats.active}</b><span>Membros ativos</span></div><div className="card"><b>{stats.unpaid}</b><span>Mensalidades não pagas</span></div><div className="card"><b>{stats.noResponse}</b><span>Sem resposta na próxima gira</span></div><div className="card"><b>{stats.questions}</b><span>Mensagens pendentes</span></div></div><div className="section-heading" style={{marginTop:20}}><div><span className="eyebrow">ATENÇÃO</span><h3>Precisa da sua atenção</h3></div></div><div className="grid"><button className="card" style={{textAlign:'left',cursor:'pointer'}} onClick={()=>action('Mensalidades','finance')}><b>💰 {stats.unpaid} filhos não pagaram</b><p className="muted small">Mensalidades do mês atual.</p><span className="pill">Ver mensalidades →</span></button><button className="card" style={{textAlign:'left',cursor:'pointer'}} onClick={()=>action('Respostas','giras')}><b>📅 {stats.noResponse} ainda não responderam</b><p className="muted small">{stats.next?stats.next.name:'Próxima gira'}.</p><span className="pill">Ver gira →</span></button><button className="card" style={{textAlign:'left',cursor:'pointer'}} onClick={()=>action('Mensagens','questions')}><b>💬 {stats.questions} mensagens aguardando resposta</b><p className="muted small">Dúvidas enviadas pela comunidade.</p><span className="pill">Ver mensagens →</span></button><button className="card" style={{textAlign:'left',cursor:'pointer'}} onClick={()=>action('Giras','giras')}><b>🧹 {stats.withoutTask} presentes sem tarefa</b><p className="muted small">{stats.next?'Participantes da próxima gira.':'Nenhuma gira futura cadastrada.'}</p><span className="pill">Organizar tarefas →</span></button></div><div className="grid" style={{marginTop:16}}><div className="card"><span className="eyebrow">PRÓXIMA GIRA</span>{stats.next?<><h3>{stats.next.name}</h3><p>{dateTime(stats.next.starts_at)}</p><div className="choice"><span className="pill">{stats.going} vão</span><span className="pill">{stats.notGoing} não vão</span><span className="pill">{stats.noResponse} sem resposta</span></div><p className="muted small" style={{marginTop:10}}>Tarefas: {stats.regularAssigned}/{stats.taskSlots||0} preenchidas</p><button className="btn" onClick={()=>action('Gira','giras')}>Gerenciar gira →</button></>:<p className="muted">Nenhuma próxima gira cadastrada.</p>}</div><div className="card"><span className="eyebrow">FINANCEIRO</span><h3>{stats.active-stats.unpaid} pagos · {stats.unpaid} não pagos</h3><p className="muted small">{stats.pendingCharges} cobranças extras pendentes · {money(stats.pendingChargeTotal)}</p><button className="btn" onClick={()=>action('Financeiro','finance')}>Abrir financeiro →</button></div></div><div className="grid" style={{marginTop:16}}><div className="card"><span className="eyebrow">CASA</span><h3>{stats.active} membros ativos</h3><p className="muted small">{(stats.attendance||[]).length?stats.going+' participam da próxima gira.':'Nenhuma gira futura para acompanhar.'}</p><p className="muted small">{stats.incomplete} cadastros incompletos · {stats.contentCount} conteúdos publicados.</p><button className="btn" onClick={()=>action('Pessoas','people')}>Ver pessoas →</button></div><div className="card"><span className="eyebrow">COMUNICAÇÃO</span><h3>{stats.questions} mensagens pendentes</h3><p className="muted small">A caixa da casa reúne dúvidas, pedidos e assuntos enviados pela comunidade.</p><button className="btn" onClick={()=>action('Mensagens','questions')}>Abrir mensagens →</button></div></div>{stats.unpaid===0&&stats.noResponse===0&&stats.questions===0&&stats.withoutTask===0&&<div className="card" style={{marginTop:16,textAlign:'center'}}><h3>✓ Tudo em dia</h3><p className="muted">Não há pendências importantes para a administração agora.</p></div>}</>}</div>}
function AdminQuestions(){const[items,setItems]=useState([]),[status,setStatus]=useState('open'),[loading,setLoading]=useState(true),[message,setMessage]=useState(''),[answers,setAnswers]=useState({});
 const load=async()=>{setLoading(true);const {data,error}=await supabase.rpc('admin_house_questions',{p_status:status});if(error)setMessage(err(error));setItems(data||[]);setLoading(false)};useEffect(()=>{load()},[status]);
 const answer=async id=>{const text=answers[id]||'';if(!text.trim())return;const {error}=await supabase.rpc('admin_answer_house_question',{p_id:id,p_answer:text});if(error)setMessage(err(error));else{setAnswers({...answers,[id]:''});load()}};
 const markRead=async id=>{await supabase.rpc('mark_house_question_read',{p_id:id});load()};
 return <div><div className="row between"><div><span className="eyebrow">CAIXA DA CASA</span><h2>Contato com os Pais</h2><p className="muted">Acompanhe, leia e responda as mensagens enviadas pela comunidade.</p></div><button className="btn" onClick={load}>Atualizar</button></div><div className="choice"><button className={'btn '+(status==='open'?'primary':'')} onClick={()=>setStatus('open')}>Em aberto</button><button className={'btn '+(status==='answered'?'primary':'')} onClick={()=>setStatus('answered')}>Respondidas</button><button className={'btn '+(status==='archived'?'primary':'')} onClick={()=>setStatus('archived')}>Arquivadas</button></div>{message&&<div className="toast">{message}</div>}{loading?<div className="card muted">Carregando…</div>:!items.length?<div className="card empty">Nenhuma mensagem nesta categoria.</div>:items.map(x=><div className="card" key={x.id}><div className="row between"><div><span className="pill">{x.is_anonymous?'ANÔNIMA':'IDENTIFICADA'}</span>{!x.is_anonymous&&x.sender_name&&<span className="muted small" style={{marginLeft:8}}>{x.sender_name}</span>}</div><span className="muted small">{new Date(x.created_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</span></div><p style={{whiteSpace:'pre-wrap',marginTop:12}}>{x.question}</p><div className="muted small">{x.read_at?'✓ Lida':'○ Não lida'} · {x.answer?'✓ Respondida':'○ Sem resposta'}</div>{!x.read_at&&<button className="btn" style={{marginTop:10}} onClick={()=>markRead(x.id)}>Marcar como lida</button>}{x.status==='open'&&<div style={{marginTop:14}}><Field label="Resposta"><textarea className="textarea" rows="4" value={answers[x.id]||''} onChange={e=>setAnswers({...answers,[x.id]:e.target.value})} placeholder="Escreva a resposta dos Pais da Casa…"/></Field><button className="btn primary" onClick={()=>answer(x.id)}>Enviar resposta</button></div>}{x.answer&&<div className="card" style={{marginTop:14,background:'#f1f5ed'}}><b>Resposta enviada</b><p style={{whiteSpace:'pre-wrap'}}>{x.answer}</p></div>}</div>)}</div>}

